// Generated by scripts/build_locales.py; edit locales/en.json instead.
const discoveryState = {providers:[],runs:[],run:null,selected:new Set(),busy:false,error:'',form:{provider:'club',platform:'youtube',topic:'',limit:10,content_type:'all',followers_min:null,followers_max:null,average_views_min:null}};
async function loadDiscovery(redraw=true){
  const data=await api('/api/discovery');discoveryState.providers=data.providers;discoveryState.runs=data.runs;
  if(discoveryState.run){const r=data.runs.find(x=>x.id===discoveryState.run.id);if(r)discoveryState.run=r;}
  if(redraw)render();
}
function providerName(id){return discoveryState.providers.find(p=>p.id===id)?.name||id;}
function discoveryStatus(status){return ({prepared:'To confirm',running:'Searching / To confirm',done:'Completed',failed:'Incomplete'})[status]||status;}
function discoveryView(){
  const d=discoveryState,f=d.form,source=d.providers.find(p=>p.id===f.provider),r=d.run;
  return pageHead('Find the right creators for your campaign','Search by game genre, content focus, and audience size, then add creators to your campaign shortlist.',`${state.user.role==='admin'?`<button data-action="connect-sources">${icon('link')}Connect database</button>`:''}<button data-action="reload-discovery">${icon('history')}Refresh progress</button>`)+`
  <div class="source-strip">${d.providers.map(p=>`<div><span class="source-dot ${p.configured?'connected':''}"></span><strong>${esc(p.name)}</strong><span>${p.verified_at?'Connected':p.configured?'Connection not checked':'Not connected'}</span></div>`).join('')}<span class="source-note">Searches use provider credits. You will confirm before each search.</span></div>
  ${!d.providers.some(p=>p.configured)?`<div class="info warning">Connect a creator database to start searching. Use your team provider account through Connect database. Without an account, you can still add creators manually to the Shortlist.</div>`:''}
  <section class="panel compact"><form id="discover-form"><fieldset ${!canEdit()||d.busy?'disabled':''}><div class="discovery-form-grid">
  ${selectField('Creator database','provider',f.provider,d.providers.map(p=>[p.id,p.name]))}
  ${selectField('Creator platform','platform',f.platform,(source?.platforms||['youtube']).map(x=>[x,({youtube:'YouTube',tiktok:'TikTok',instagram:'Instagram',twitch:'Twitch'})[x]]))}
  ${field('What kind of creators are you looking for?','topic',f.topic,'text',true,f.provider==='nox'?'For example:  strategy games, PC gaming; comma-separated keywords must all match.':'Enter a game, genre, or content direction, such as strategy game reviews or  strategy games.',true)}
  ${field('Minimum followers','followers_min',f.followers_min,'number')}${field('Maximum followers','followers_max',f.followers_max,'number')}
  ${selectField('Content type','content_type',f.content_type,f.platform==='youtube'?[['all','All content'],['long','Long video'],['short','YouTube Shorts']]:[['all',f.platform==='twitch'?'Live viewing':'All content']])}
  ${field('Minimum average views','average_views_min',f.average_views_min,'number',false,'Uses the content type selected above. Leave blank for no minimum.')}
  ${selectField('Maximum creators in this batch','limit',f.limit,[[5,'5 creators'],[10,'10 creators'],[20,'20 creators']])}
  </div><div class="search-foot"><p>Looking for a particular market or language? Include it in your description. Verify content language, audience location, and player fit after searching.</p><button class="primary" type="submit" ${d.busy||!source?.configured?'disabled':''}>${icon('search')}${d.busy?'Finding creators...':'Review conditions and credits'}</button></div></fieldset></form></section>
  ${d.error?`<div class="info error">${esc(d.error)}</div>`:''}
  <div class="discovery-layout"><section class="panel"><div class="panel-head"><div><div class="panel-title">${r?.status==='done'?'Creators found in this search':'Creators found'}</div><div class="panel-sub">${r?`${esc(providerName(r.query.provider))} · ${esc(r.query.platform)} · Page ${r.page} · ${esc(discoveryStatus(r.status))}`:'Search results are saved here for review and selection.'}</div></div>${r?.fetched_at?`<button class="ghost small" data-action="download-search" data-id="${r.id}">${icon('download')}Download search archive</button>`:''}</div>
  ${r?discoveryResults(r):`<div class="empty">${icon('search')}<h2>Who would you like to work with?</h2><p>Set your criteria above and confirm service credits to begin. Add results to the shortlist, then compare content, audience, and quotes.</p></div>`}</section>
  <aside class="panel search-history"><div class="panel-head"><div class="panel-title">Search history</div><span class="version">Latest  25 searches</span></div>${d.runs.length?d.runs.map(run=>`<button class="history-run ${r?.id===run.id?'active':''}" data-action="open-search" data-id="${run.id}"><strong>${esc(run.query.topic)}</strong><span>${esc(providerName(run.query.provider))} · Page ${run.page}</span><small>${when(run.created_at)} · ${esc(discoveryStatus(run.status))}${run.status==='done'?` · ${run.items.length} creator${run.items.length===1?'':'s'}`:''}</small></button>`).join(''):'<p class="blank">No creator searches yet.</p>'}</aside></div>`;
}
function discoveryResults(r){
  if(r.status==='prepared')return `<div class="empty"><h2>Search conditions ready</h2><p>Confirm the conditions and service credits to start finding creators.</p>${canEdit()?`<button class="primary" data-action="confirm-search" data-id="${r.id}">Review conditions and credits</button>`:''}</div>`;
  if(r.status==='running')return '<div class="empty"><h2>Waiting for provider search results</h2><p>Refresh progress to view saved results without running another search. If the wait is long or the app closed, check the provider credit history first.</p></div>';
  if(r.status==='failed')return `<div class="empty"><h2>This search did not complete</h2><p>${esc(r.error||'Check the provider account and available credits.')}</p></div>`;
  if(!r.items.length)return '<div class="empty"><h2>No creators matched this search</h2><p>Try another content focus or relax follower and view requirements before searching again.</p></div>';
  const hasProject=!!state.pid;
  return `<div class="search-result-note">Search: ${esc(r.query.topic)} · Searched at  ${when(r.fetched_at)}. Ordered by the provider, not a verified fit ranking. Creator location does not establish audience location.</div><div class="discovered-list">${r.items.map((x,i)=>`<article class="discovered-card"><div class="discovered-head">${canEdit()?`<input type="checkbox" data-discovered="${i}" ${discoveryState.selected.has(i)?'checked':''} ${!x.importable?'disabled':''} aria-label="Select  ${esc(x.name)}">`:''}${avatar(x.name,i)}<div><strong>${esc(x.name)}</strong><span class="subline">${esc(x.platform)}${x.account_id?' · '+esc(x.account_id):''}${r.query.provider==='nox'?' · Provider may mask names':''}</span></div>${x.profile_url?`<a href="${esc(x.profile_url)}" target="_blank" rel="noopener noreferrer" class="profile-link">Profile ${icon('link')}</a>`:''}</div><div class="discovered-stats"><div><span>followers / subscribers</span><b>${num(x.followers)}</b></div><div><span>${esc(x.metric_label)}</span><b>${num(x.average_views)}</b></div><div><span>Creator location</span><b>${esc(x.creator_location||'Not provided')}</b></div></div>${x.tags?`<p class="discovered-tags">${esc(x.tags)}</p>`:''}${x.description?`<p class="discovered-bio">${esc(x.description)}</p>`:''}<details><summary>Still to verify</summary><ul>${x.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></details></article>`).join('')}</div><div class="search-import-bar"><div><strong id="discovery-selected-count">Selected  ${discoveryState.selected.size} creator${discoveryState.selected.size===1?'':'s'}</strong><span>${hasProject?`Add to: ${esc(state.data.project.name)}`:'Create a campaign first, then save these creators to its shortlist.'}</span></div>${canEdit()?hasProject?'<button class="primary" data-action="import-search">Add to campaign shortlist</button>':'<button class="primary" data-action="new-project">Create campaign</button>':''}</div><div class="table-footer"><span>Saved ${r.items.length} creator${r.items.length===1?'':'s'} · Revisit these results without additional search charges</span>${r.more_available&&canEdit()?`<button class="small" data-action="next-search" data-id="${r.id}">Find the next batch ${icon('arrow')}</button>`:'<span>All available results shown</span>'}</div>`;
}
function sourceModal(){
  modal('Connect your team creator database','Connect a provider account your team already uses. Once connected, you can search here.',`<div class="info">Save the access key, then check the connection. This does not search for creators or spend search credits. Reconnect after stopping the app.</div><div class="source-settings">${discoveryState.providers.map(p=>`<form class="source-form" data-provider="${p.id}"><h3>${esc(p.name)}</h3><p>${p.verified_at?'Connected; ready to search':p.configured?'Saved; check connection':'Not connected'} · ${p.platforms.map(x=>x.toUpperCase()).join(' / ')}</p><label class="field"><span>Provider access key</span><input type="password" name="key" autocomplete="off" placeholder="Paste the access key from the provider dashboard" required></label><div class="actions spacer"><button type="submit" class="primary small">Save access key</button><button type="button" class="small" data-action="check-source" data-provider="${p.id}" ${!p.configured?'disabled':''}>Check connection</button><button type="button" class="ghost small" data-action="clear-source" data-provider="${p.id}" ${!p.configured?'disabled':''}>Disconnect</button><a href="${esc(p.portal)}" target="_blank" rel="noopener noreferrer">Open provider dashboard</a></div><details class="spacer"><summary>Where do I find the access key?</summary><p>Open the provider dashboard above and look for  API Key(the access key for tools). This is not your login password. If unavailable, ask the account owner whether the plan supports it. Never enter the key in search descriptions or campaign notes.</p></details><div class="source-check-result" data-provider="${p.id}"></div></form>`).join('')}</div>`);
  $$('.source-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const button=$('button[type=submit]',form);button.disabled=true;try{const data=await api('/api/discovery/config',{method:'POST',body:{provider:form.dataset.provider,key:form.elements.key.value}});form.reset();discoveryState.providers=data.providers;render();sourceModal();toast('Access key saved. Check the connection when ready; no creator search has run.');}finally{button.disabled=false;}});}));
}
function searchPreviewModal(plan){
  const q=plan.query;
  modal('Confirm this creator search','Search only this batch. Finding more creators requires another credit confirmation.',`<dl class="snapshot-grid"><dt>Creator database</dt><dd>${esc(providerName(q.provider))}</dd><dt>Platform</dt><dd>${esc(q.platform)}</dd><dt>Search description</dt><dd>${esc(q.topic)}</dd><dt>Follower range</dt><dd>${q.followers_min==null?'No minimum':num(q.followers_min)} to ${q.followers_max==null?'No maximum':num(q.followers_max)}</dd><dt>Content type / Minimum average views</dt><dd>${({all:'All content',long:'Long video',short:'YouTube Shorts'})[q.content_type]} / ${q.average_views_min==null?'No minimum views':num(q.average_views_min)}</dd><dt>Search size</dt><dd>Page ${plan.page}, up to  ${q.limit} creator${q.limit===1?'':'s'}</dd><dt>Estimated usage</dt><dd>Up to approximately ${esc(plan.price.estimated_credit)} service credits (not money)</dd></dl><div class="info warning">${esc(plan.price.basis)} No contact lookup, profile unlock, or outreach runs automatically.</div><div class="info">${q.provider==='club'?'A long- or short-video filter confirms that the creator has published that format, not that it is their primary format.':'The provider may mask names. Verify the actual account and profile before agreeing to a partnership.'} Markets and languages in the description are search clues only. Verify the actual audience market separately.</div><form id="confirm-search-form"><label class="check-field"><input type="checkbox" required name="accept_cost"><span>I confirm these conditions and agree to use this provider account service credits.</span></label><div class="form-footer"><button type="button" data-action="close">Edit conditions</button><button type="submit" class="primary">Confirm and find creators</button></div></form>`);
  $('#confirm-search-form').addEventListener('submit',e=>{e.preventDefault();run(async()=>{
    const button=$('button[type=submit]',e.target);button.disabled=true;closeModal(true);discoveryState.busy=true;discoveryState.error='';discoveryState.run={...plan,status:'running'};discoveryState.selected.clear();render();
    try{discoveryState.run=await api('/api/discovery/runs/'+plan.id+'/execute',{method:'POST',body:{accept_cost:true}});toast(`Found  ${discoveryState.run.items.length} creator${discoveryState.run.items.length===1?'':'s'}.`);}catch(err){discoveryState.error=err.message;}finally{discoveryState.busy=false;await loadDiscovery();}
  });});
}
async function prepareSearch(body){
  discoveryState.busy=true;discoveryState.error='';render();
  try{const plan=await api('/api/discovery/preview',{method:'POST',body});discoveryState.run=plan;discoveryState.selected.clear();await loadDiscovery(false);searchPreviewModal(plan);}
  catch(err){discoveryState.error=err.message;}
  finally{discoveryState.busy=false;render();}
}
function bindDiscovery(){
  const form=$('#discover-form');if(!form)return;
  form.addEventListener('input',()=>{discoveryState.form={...readForm(form),limit:Number(form.elements.limit.value)};});
  form.addEventListener('change',e=>{discoveryState.form={...readForm(form),limit:Number(form.elements.limit.value)};
    if(e.target.name==='provider'){const source=discoveryState.providers.find(p=>p.id===e.target.value);if(!source.platforms.includes(discoveryState.form.platform))discoveryState.form.platform=source.platforms[0];render();}
    else if(e.target.name==='platform'){if(e.target.value!=='youtube')discoveryState.form.content_type='all';render();}
  });
  form.addEventListener('submit',e=>{e.preventDefault();run(()=>prepareSearch({...readForm(form),limit:Number(form.elements.limit.value)}));});
}
document.addEventListener('click',e=>{
  const button=e.target.closest('[data-action]');if(!button)return;
  const action=button.dataset.action;
  run(async()=>{
    if(action==='connect-sources')sourceModal();
    if(action==='reload-discovery')await loadDiscovery();
    if(action==='clear-source'){const data=await api('/api/discovery/config',{method:'POST',body:{provider:button.dataset.provider,key:''}});discoveryState.providers=data.providers;render();sourceModal();}
    if(action==='check-source'){button.disabled=true;const output=$(`.source-check-result[data-provider="${button.dataset.provider}"]`);output.textContent='Checking the provider account...';try{await api('/api/discovery/check',{method:'POST',body:{provider:button.dataset.provider}});await loadDiscovery(false);output.textContent='Account is available. No creator search was run during this check.';render();}catch(err){output.textContent=err.message;}finally{button.disabled=false;}}
    if(action==='open-search'){discoveryState.run=await api('/api/discovery/runs/'+button.dataset.id);discoveryState.selected.clear();discoveryState.error='';render();}
    if(action==='confirm-search')searchPreviewModal(discoveryState.runs.find(r=>r.id===button.dataset.id)||discoveryState.run);
    if(action==='download-search')window.location='/api/discovery/runs/'+button.dataset.id+'/raw';
    if(action==='next-search')await prepareSearch({parent_id:button.dataset.id});
    if(action==='import-search'){
      if(!discoveryState.selected.size)throw new Error('Select creators to add to the shortlist first.');
      button.disabled=true;const projectId=state.pid,runId=discoveryState.run.id;
      try{const result=await api('/api/discovery/runs/'+runId+'/import',{method:'POST',body:{project_id:projectId,indices:[...discoveryState.selected]}});discoveryState.selected.clear();await refresh();toast(`Added to shortlist:  ${result.count} creator${result.count===1?'':'s'}; ${result.skipped} already on the shortlist; not added again.`);}finally{button.disabled=false;}
    }
  });
});
document.addEventListener('change',e=>{
  if(e.target.matches('[data-discovered]')){const i=Number(e.target.dataset.discovered);if(e.target.checked)discoveryState.selected.add(i);else discoveryState.selected.delete(i);$('#discovery-selected-count').textContent=`Selected  ${discoveryState.selected.size} creator${discoveryState.selected.size===1?'':'s'}`;}
});
